import{reactive,computed}from"vue";import{defineStore}from"pinia";export const useAddressSettingsStore=defineStore("AddressSettings",()=>{const settings=reactive({previewConfig:null});const form=reactive({subfields:[],showMapOnLoad:"coords",onSearch:"open",visibilityToggle:"both",coordinatesMode:"editable",requireCoordinates:false});const previewConfig=computed(()=>{return{subfieldConfig:form.subfields.map(({key,label,width,show,auto,req})=>({handle:key,label:label,width:width,enabled:!!show,autocomplete:!!auto,required:!!req})),visibilityToggle:form.visibilityToggle,coordinatesMode:form.coordinatesMode,mapOnSearch:form.onSearch,showMap:form.showMapOnLoad!=="closed",requireCoordinates:!!form.requireCoordinates}});function setFromDom(root){const getDropdownValue=name=>{const el=root.querySelector(`[name$="[${name}]"]`);if(!el){return undefined}return el.value};const getLightswitchValue=settingName=>{const hidden=root.querySelector(`input[type="hidden"][name$="[${settingName}]"]`);if(!hidden){return null}const btn=hidden.closest(".lightswitch-outer-container")?.querySelector(".lightswitch");if(!btn){return null}return btn.getAttribute("aria-checked")==="true"};const readTextField=(row,index,suffix)=>{const el=row.querySelector(`textarea[name$="[${index}][${suffix}]"],`+`input[type="text"][name$="[${index}][${suffix}]"]`);if(!el){return""}return el.value??""};const readNumberField=(row,index,suffix)=>{const el=row.querySelector(`input[type="number"][name$="[${index}][${suffix}]"]`);if(!el){return 0}const value=el.value;if(value===undefined||value===null||value===""){return 0}return Number(value)};const readBooleanField=(row,index,suffix)=>{let el=row.querySelector(`input[type="checkbox"][name*="[subfieldConfig][${index}][${suffix}]"]`);if(el){return!!el.checked}el=row.querySelector(`input[type="hidden"][name*="[subfieldConfig][${index}][${suffix}]"]`);if(el){const val=(el.value||"").toString().toLowerCase();return val==="1"||val==="true"||val==="on"}if(suffix==="enabled"){const isDisabled=row.classList.contains("disabled");return!isDisabled}return false};const rows=root.querySelectorAll("[data-gm-subfield-row]");const result=[];rows.forEach(row=>{const key=row.getAttribute("data-key");if(!key){return}const index=row.getAttribute("data-index");if(!index){return}const label=readTextField(row,index,"label");const width=readNumberField(row,index,"width")||100;const show=readBooleanField(row,index,"enabled");const auto=readBooleanField(row,index,"autocomplete");const req=readBooleanField(row,index,"required");result.push({key:key,label:label,width:width,show:show,auto:auto,req:req})});form.subfields=result;const rawStart=getDropdownValue("mapOnStart");if(rawStart){form.mapOnStart=rawStart;form.showMapOnLoad=rawStart==="default"?"coords":rawStart==="open"?"open":"closed"}const mapOnSearch=getDropdownValue("mapOnSearch");if(mapOnSearch){form.mapOnSearch=mapOnSearch;form.onSearch=mapOnSearch}const visibilityToggle=getDropdownValue("visibilityToggle");if(visibilityToggle){form.visibilityToggle=visibilityToggle}const coordinatesMode=getDropdownValue("coordinatesMode");if(coordinatesMode){form.coordinatesMode=coordinatesMode}form.requireCoordinates=getLightswitchValue("requireCoordinates");if(typeof settings!=="undefined"){settings.previewConfig={subfieldConfig:result.map(sf=>({key:sf.key,handle:sf.key,label:sf.label,width:sf.width,enabled:sf.show,required:sf.req,autocomplete:sf.auto})),mapOnStart:form.mapOnStart??null,mapOnSearch:form.mapOnSearch??null,visibilityToggle:form.visibilityToggle??null,coordinatesMode:form.coordinatesMode??null,requireCoordinates:!!form.requireCoordinates}}}function applyRowUi(row){const index=row.getAttribute("data-index");if(!index){return}const enabledEl=row.querySelector(`input[type="checkbox"][name*="[subfieldConfig][${index}][enabled]"]`);const isEnabled=enabledEl?!!enabledEl.checked:true;row.classList.toggle("disabled",!isEnabled);const labelEl=row.querySelector(`textarea[name$="[${index}][label]"], input[type="text"][name$="[${index}][label]"]`);if(labelEl){labelEl.disabled=!isEnabled}}function bindDomListeners(root){root.querySelectorAll("[data-gm-subfield-row]").forEach(applyRowUi);root.querySelectorAll("[data-gm-subfield-row] input, "+"[data-gm-subfield-row] select, "+"[data-gm-subfield-row] textarea").forEach(el=>{const onChange=()=>{const row=el.closest("[data-gm-subfield-row]");if(row){applyRowUi(row)}setFromDom(root)};el.addEventListener("input",onChange);el.addEventListener("change",onChange)});root.addEventListener("gm:subfields:reordered",()=>{setFromDom(root)});root.querySelectorAll("[data-gm-settings-select], [data-gm-settings-checkbox]").forEach(el=>{el.addEventListener("change",()=>setFromDom(root))});const settingNames=["mapOnStart","mapOnSearch","visibilityToggle","coordinatesMode"];settingNames.forEach(name=>{root.querySelectorAll(`[name$="[${name}]"]`).forEach(el=>{if(el.__gmSettingsBound){return}el.addEventListener("change",()=>setFromDom(root));el.__gmSettingsBound=true})});const hidden=root.querySelector('input[type="hidden"][name$="[requireCoordinates]"]');const btn=hidden?.closest(".lightswitch-outer-container")?.querySelector(".lightswitch");if(btn&&!btn.__gmSettingsBound){btn.addEventListener("click",()=>{setFromDom(root)});btn.__gmSettingsBound=true}const table=root.querySelector("table.gm-subfields");if(table&&window.Garnish&&window.Garnish.DragSort&&window.$){if(!table.__gmSubfieldDragSort){const $table=window.$(table);const reindexRows=()=>{const rows=table.querySelectorAll("tbody [data-gm-subfield-row]");rows.forEach((row,newIndex)=>{const newIdx=String(newIndex);const oldIdx=row.getAttribute("data-index");if(oldIdx===newIdx){return}row.setAttribute("data-index",newIdx);row.querySelectorAll("input[name], textarea[name], select[name]").forEach(inp=>{const oldName=inp.getAttribute("name");if(!oldName){return}const updated=oldName.replace(/\[subfieldConfig]\[\d+]/,`[subfieldConfig][${newIdx}]`);if(updated!==oldName){inp.setAttribute("name",updated)}})});root.dispatchEvent(new CustomEvent("gm:subfields:reordered",{bubbles:true}))};table.__gmSubfieldDragSort=new window.Garnish.DragSort($table.find("tbody tr"),{handle:".move",axis:"y",collapseDraggees:true,onSortChange:reindexRows})}}}return{form:form,previewConfig:previewConfig,setFromDom:setFromDom,bindDomListeners:bindDomListeners}});